const { spawn } = require('node:child_process');
const wrapper = spawn('cmd.exe', ['/d', '/s', '/c', process.execPath, '-e', 'console.log(process.pid);setInterval(()=>{},1000)'], {stdio:['ignore','pipe','inherit'], windowsHide:true});
let text='';
wrapper.stdout.setEncoding('utf8');
wrapper.stdout.on('data', async chunk => {
  text += chunk;
  const match = text.match(/\d+/);
  if (!match) return;
  wrapper.stdout.removeAllListeners('data');
  const descendant = Number(match[0]);
  const before = isAlive(descendant);
  const killResult = wrapper.kill();
  await new Promise(resolve => wrapper.once('exit', resolve));
  const wrapperRunning = wrapper.exitCode === null && wrapper.signalCode === null;
  const after = isAlive(descendant);
  console.log(JSON.stringify({wrapperPid:wrapper.pid, descendantPid:descendant, before, killResult, wrapperExitCode:wrapper.exitCode, wrapperSignalCode:wrapper.signalCode, wrapperRunning, descendantAliveAfterWrapperExit:after}));
  if (after) process.kill(descendant);
});
function isAlive(pid) { try { process.kill(pid, 0); return true; } catch { return false; } }
setTimeout(() => { console.error('probe timeout'); try { wrapper.kill(); } catch {} process.exitCode=1; }, 10000).unref();
